{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table hox_db.maplemonk.hox_db_yfl_summary_stock_reorder as with sku_masters as ( select * from (select distinct replace(marketplace_sku,\'\`\',\'\') marketplace_sku ,replace(master_sku,\'\`\',\'\') master_sku ,row_number() over (partition by replace(marketplace_sku,\'\`\',\'\') order by 1) rw from HOX_DB.MAPLEMONK.sku_master ) where rw=1 ), cog_price as ( select distinct sku, (cost:: float) as cost, WEIGHT from hox_db.maplemonk.EASYECOM_YFLHOME_PRODUCT_MASTER where lower(PRODUCT_TYPE) in (\'normal_product\', \'child_product\') union select distinct MODEL_NO, (cost:: float) as cost, WEIGHT from hox_db.maplemonk.EASYECOM_YFLHOME_PRODUCT_MASTER where lower(PRODUCT_TYPE) in (\'normal_product\', \'child_product\') ), sales_quantity as ( select case when lower(source) = \'amazon\' then \'Amazon FBA\' else \'Easyecom\' end as source, reference_code, date(order_date) as order_date, coalesce(a.master_sku, o.sku_code)as sku_code, PRODUCT_CATEGORY, case when lower(source) = \'amazon\' then \'Amazon warehouse\' else WAREHOUSE end as WAREHOUSE, sum(coalesce(quantity,0)) as total_quantity from HOX_DB.MAPLEMONK.HOX_DB_YFLHome_sales_consolidated o left join sku_masters a on lower(o.sku_code) = lower(a.marketplace_sku) where lower(order_status) not like \'%cancel%\' group by 1,2,3,4,5,6 ), fba_stock as ( select coalesce(c.new_sku , a.sku) as component_sku_name, \'Amazon warehouse\' as Warehouse, Sum(ifnull(c.item_count,1) * a.fba_inventory) as QUANTITY, Sum(ifnull(c.item_count,1) * a.fba_bad_inventory) as bad_QUANTITY from ( select coalesce(a.master_sku, o.SKU) as SKU, fba_inventory, fba_bad_inventory from ( select o.sku, sum(\"afn-fulfillable-quantity\") AS fba_inventory, SUM(\"afn-unsellable-quantity\") AS fba_bad_inventory from ( Select * , ROW_NUMBER() OVER(PARTITION BY SKU order by _AIRBYTE_EMITTED_AT desc) as rn from HOX_DB.MapleMonk.YFL_GET_FBA_MYI_ALL_INVENTORY_DATA where lower(\"afn-listing-exists\") = \'yes\' )as o where rn = 1 group by 1 )o left join ( select distinct marketplace_sku,master_sku from sku_masters )a on lower(o.SKU) = lower(a.marketplace_sku) )as a left join hox_db.maplemonk.hox_db_Sku_child_mapping c on lower(a.SKU) = lower(c.sku_code) group by 1, 2 order by 3 ), base_final as ( select new_sku, PRODUCT_CATEGORY as sku_type, round(Sum(case when source = \'Easyecom\' and (order_date between (current_date - 7) and (current_date - 1)) then final_quantity end)/7, 2) as EE_DRR_7day, round(Sum(case when source = \'Easyecom\' and (order_date between (current_date - 30) and (current_date - 1)) then final_quantity end)/30, 2) as EE_DRR_30day, round(Sum(case when source = \'Easyecom\' and (order_date between (current_date - 60) and (current_date - 1)) then final_quantity end)/60, 2) as EE_DRR_60day, round(Sum(case when source = \'Easyecom\' and (order_date between (current_date - 14) and (current_date - 1)) then final_quantity end)/14, 2) as EE_DRR_14day, round(Sum(case when source =\'Easyecom\' and warehouse = \'YFL BLR\' and (order_date between (current_date - 7) and (current_date - 1)) then final_quantity end)/7, 2) as EE_DRR_7day_BLR, round(Sum(case when source =\'Easyecom\' and warehouse = \'YFL BLR\' and (order_date between (current_date - 30) and (current_date - 1)) then final_quantity end)/30, 2) as EE_DRR_30day_BLR, round(Sum(case when source =\'Easyecom\' and warehouse = \'YFL BLR\' and (order_date between (current_date - 60) and (current_date - 1)) then final_quantity end)/60, 2) as EE_DRR_60day_BLR, round(Sum(case when source =\'Easyecom\' and warehouse = \'YFL BLR\' and (order_date between (current_date - 14) and (current_date - 1)) then final_quantity end)/14, 2) as EE_DRR_14day_BLR, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL GGN\' and (order_date between (current_date - 7) and (current_date - 1)) then final_quantity end)/7, 2) as EE_DRR_7day_GGN, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL GGN\' and (order_date between (current_date - 30) and (current_date - 1)) then final_quantity end)/30, 2) as EE_DRR_30day_GGN, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL GGN\' and (order_date between (current_date - 60) and (current_date - 1)) then final_quantity end)/60, 2) as EE_DRR_60day_GGN, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL GGN\' and (order_date between (current_date - 14) and (current_date - 1)) then final_quantity end)/14, 2) as EE_DRR_14day_GGN, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL MUM\' and (order_date between (current_date - 7) and (current_date - 1)) then final_quantity end)/7, 2) as EE_DRR_7day_MUM, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL MUM\' and (order_date between (current_date - 30) and (current_date - 1)) then final_quantity end)/30, 2) as EE_DRR_30day_MUM, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL MUM\' and (order_date between (current_date - 60) and (current_date - 1)) then final_quantity end)/60, 2) as EE_DRR_60day_MUM, round(Sum(case when source =\'Easyecom\' and warehouse =\'YFL MUM\' and (order_date between (current_date - 14) and (current_date - 1)) then final_quantity end)/14, 2) as EE_DRR_14day_MUM, round(Sum(case when source = \'Amazon FBA\' and (order_date between (current_date - 7) and (current_date - 1)) then final_quantity end)/7,2) as FBA_DRR_7day, round(Sum(case when source = \'Amazon FBA\' and (order_date between (current_date - 30) and (current_date - 1)) then final_quantity end)/30,2) as FBA_DRR_30day, round(Sum(case when source = \'Amazon FBA\' and (order_date between (current_date - 60) and (current_date - 1)) then final_quantity end)/60,2) as FBA_DRR_60day, round(Sum(case when source = \'Amazon FBA\' and (order_date between (current_date - 14) and (current_date - 1)) then final_quantity end)/14,2) as FBA_DRR_14day, from ( select distinct a.* , COALESCE(b.new_sku, a.sku_code) AS NEW_SKU, round(coalesce(b.item_count:: int, 1),1) as item_count, (total_quantity * round(coalesce(b.item_count:: int, 1),1))as final_quantity from sales_quantity a left join hox_db.maplemonk.hox_db_Sku_child_mapping b on lower(a.sku_code) = lower(b.sku_code) )as o Group by 1,2 ), base_aggregate as ( select distinct o.* , coalesce(a.QUANTITY,0) as total_quantity_FBA, coalesce(bad_QUANTITY, 0) as bad_QUANTITY_FBA from ( select sku, COALESCE(sum(case when new_location = \'YFL BLR\' then AVAILABLE_INVENTORY end),0) as total_quantity_Emiza_BLR, COALESCE(sum(case when new_location = \'YFL GGN\' then AVAILABLE_INVENTORY end),0) as total_quantity_Emiza_GGN, COALESCE(sum(case when new_location = \'YFL MUM\' then AVAILABLE_INVENTORY end),0) as total_quantity_Emiza_MUM, ( COALESCE(sum(case when new_location = \'YFL BLR\' then AVAILABLE_INVENTORY end),0) + COALESCE(sum(case when new_location = \'YFL GGN\' then AVAILABLE_INVENTORY end),0) + COALESCE(sum(case when new_location = \'YFL MUM\' then AVAILABLE_INVENTORY end),0) ) as total_quantity_Emiza, coalesce(sum(bad_inventory),0) as bad_inventory, COALESCE(sum(case when new_location = \'YFL BLR\' then bad_inventory end),0) as Bad_quantity_Emiza_BLR, COALESCE(sum(case when new_location = \'YFL GGN\' then bad_inventory end),0) as Bad_quantity_Emiza_GGN, COALESCE(sum(case when new_location = \'YFL MUM\' then bad_inventory end),0) as Bad_quantity_Emiza_MUM from ( select ROW_NUMBER() over (partition by sku, new_location order by data_fetch_date:: timestamp desc) rw, (coalesce(REPAIR,0) + coalesce(DAMAGED,0) + coalesce(\"Total Lost\",0) + coalesce(\"Discard/Fraud\",0) + coalesce(\"Undispatched Unassigned Quantity\",0)) as bad_inventory, * from ( select case when trim(UPPER(location)) in (\'YOUR FOOD LAB (GGN)\', \'YFL_GURGAON\', \'YOUR FOOD LAB\') then \'YFL GGN\' when trim(upper(location)) in (\'YOUR FOOD LAB (MUM)\') then \'YFL MUM\' when trim(upper(location)) in (\'YOUR FOOD LAB (BLR)\') then \'YFL BLR\' else location end as new_location, * from hox_db.maplemonk.hox_db_YFLHOME_summary_inventory_sku_sales )o )as o where o.rw = 1 group by 1 order by 4 desc )o left join fba_stock a on lower(o.sku) = lower(a.component_sku_name) ) select o.*, a.cost as COGS, round(a.cost * TOTAL_QUANTITY_EMIZA, 2) as Emiza_cogs, round(a.cost * TOTAL_QUANTITY_FBA, 2) as FBA_cogs, case when \"Days of Inventory Emiza 30day\" <= 60 then \'YES\' else \'NO\' end as \"Re-order required Emiza\", case when \"Days of Inventory Emiza 30day\" <= 60 then round(EE_DRR_30day * 75,0) else null end as \"Re-order units\", case when \"Days of Inventory FBA 30day\" <= 60 then \'YES\' else \'NO\' end as \"Re-order required FBA\", case when \"Days of Inventory FBA 30day\" <= 60 then round(FBA_DRR_30day * 75,0) else null end as \"Re-order units FBA\", case when \"Days of Inventory BLR Emiza 30day\" <= 60 then \'YES\' else \'NO\' end as \"Re-order required Emiza BLR\", case when \"Days of Inventory BLR Emiza 30day\" <= 60 then round(EE_DRR_30day_BLR * 75,0) else null end as \"Re-order units Emiza BLR\", case when \"Days of Inventory GGN Emiza 30day\" <= 60 then \'YES\' else \'NO\' end as \"Re-order required Emiza GGN\", case when \"Days of Inventory GGN Emiza 30day\" <= 60 then round(EE_DRR_30day_GGN * 75,0) else null end as \"Re-order units Emiza GGN\", case when \"Days of Inventory MUM Emiza 30day\" <= 60 then \'YES\' else \'NO\' end as \"Re-order required Emiza MUM\", case when \"Days of Inventory MUM Emiza 30day\" <= 60 then round(EE_DRR_30day_MUM * 75,0) else null end as \"Re-order units Emiza MUM\" from ( Select o.*, round(coalesce((total_quantity_Emiza *1.00 / nullif(EE_DRR_30day,0)),0),2) as \"Days of Inventory Emiza 30day\", round(coalesce((total_quantity_Emiza *1.00 / nullif(EE_DRR_60day,0)),0),2) as \"Days of Inventory Emiza 60day\", round(coalesce((total_quantity_FBA *1.00 / nullif(FBA_DRR_30day,0)),0),2) as \"Days of Inventory FBA 30day\", round(coalesce((total_quantity_FBA *1.00 / nullif(FBA_DRR_60day,0)),0),2) as \"Days of Inventory FBA 60day\", round(coalesce((total_quantity_Emiza_BLR *1.00 / nullif(EE_DRR_30day_BLR,0)),0),2) as \"Days of Inventory BLR Emiza 30day\", round(coalesce((total_quantity_Emiza_BLR *1.00 / nullif(EE_DRR_60day_BLR,0)),0),2) as \"Days of Inventory BLR Emiza 60day\", round(coalesce((total_quantity_Emiza_GGN *1.00 / nullif(EE_DRR_30day_GGN,0)),0),2) as \"Days of Inventory GGN Emiza 30day\", round(coalesce((total_quantity_Emiza_GGN *1.00 / nullif(EE_DRR_60day_GGN,0)),0),2) as \"Days of Inventory GGN Emiza 60day\", round(coalesce((total_quantity_Emiza_MUM *1.00 / nullif(EE_DRR_30day_MUM,0)),0),2) as \"Days of Inventory MUM Emiza 30day\", round(coalesce((total_quantity_Emiza_MUM *1.00 / nullif(EE_DRR_60day_MUM,0)),0),2) as \"Days of Inventory MUM Emiza 60day\" from ( select a.*, coalesce(b.total_quantity_Emiza,0) as total_quantity_Emiza, coalesce(b.total_quantity_FBA,0) as total_quantity_FBA, coalesce(b.bad_QUANTITY_FBA,0) as bad_QUANTITY_FBA, coalesce(b.total_quantity_Emiza_BLR,0) as total_quantity_Emiza_BLR, coalesce(b.total_quantity_Emiza_GGN,0) as total_quantity_Emiza_GGN, coalesce(b.total_quantity_Emiza_MUM,0) as total_quantity_Emiza_MUM, coalesce(b.bad_inventory,0) as bad_inventory, coalesce(b.Bad_quantity_Emiza_BLR,0) as Bad_quantity_Emiza_BLR, coalesce(b.Bad_quantity_Emiza_GGN,0) as Bad_quantity_Emiza_GGN, coalesce(b.Bad_quantity_Emiza_MUM,0) as Bad_quantity_Emiza_MUM from base_final a LEFT JOIN base_aggregate b ON lower(a.new_sku) = lower(b.sku) )as o )as o left join cog_price a on lower(o.new_sku) = lower(a.sku) where o.new_sku <> \'BLKCAP_FR_01\' order by 1",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from HOX_DB.information_schema.databases
            ),
            
            final as (
